"use strict";(globalThis.webpackChunknative_update_docs=globalThis.webpackChunknative_update_docs||[]).push([[1350],{51313(e){e.exports=JSON.parse('{"tag":{"label":"developers","permalink":"/tags/developers","allTagsPath":"/tags","count":7,"items":[{"id":"developers/access-tokens","title":"Access tokens and app keys","description":"The two kinds of Native Update credential. An nu_app_ key ships inside your app and only checks for updates; an nu_pat_ access token manages your own apps through the API and never leaves your server or CI.","permalink":"/developers/access-tokens"},{"id":"developers/assistants","title":"Connect Claude, ChatGPT, Claude Code or Cursor","description":"Connect an AI app to Native Update over MCP so it can check releases and change rollouts with the permissions you tick. Deletes wait for your yes, and disconnecting ends its access at once.","permalink":"/developers/assistants"},{"id":"developers/changelog","title":"Developer changelog","description":"Changes to Native Update\'s Public Management API, MCP server, webhooks and two-step sign-in, newest first.","permalink":"/developers/changelog"},{"id":"developers/index","title":"Native Update for developers","description":"Drive your Native Update apps, builds and rollouts from outside the dashboard, with an access token and the API, an AI app such as Claude or ChatGPT, or webhooks to your own server.","permalink":"/developers/"},{"id":"developers/api","title":"The Public Management API","description":"Where the Native Update Public Management API lives, how a call is authenticated and limited, and the OpenAPI 3.1 document the backend generates from its own routes.","permalink":"/developers/api"},{"id":"developers/two-step-sign-in","title":"Two-step sign-in","description":"Turn on two-step sign-in for your Native Update account, keep ten recovery codes, remember a browser for 7 days if you choose, and see what still asks for a code. Covers the dashboard and the Nova admin panel.","permalink":"/developers/two-step-sign-in"},{"id":"developers/webhooks","title":"Webhooks","description":"Native Update sends a signed POST to your own server each time a build, an app or an app key changes. Every event with a sample payload, signature checks in Node and PHP, retries, pausing and the addresses that are refused.","permalink":"/developers/webhooks"}],"unlisted":false}}')}}]);